var rng = new Random(42);

// Day A: every request takes 20-200 ms
var dayA = Enumerable.Range(0, 10_000)
    .Select(_ => 20 + rng.NextDouble() * 180).ToArray();

// Day B: 95% cache hits (20-80 ms), 5% misses (600-2,000 ms)
var dayB = Enumerable.Range(0, 10_000)
    .Select(_ => rng.NextDouble() < 0.05
        ? 600 + rng.NextDouble() * 1_400
        : 20 + rng.NextDouble() * 60).ToArray();

Console.WriteLine($"Day A: mean {dayA.Average():F0} ms");
Console.WriteLine($"Day B: mean {dayB.Average():F0} ms");
// Day A: mean 110 ms
// Day B: mean 109 ms

var rng = new Random(42);

// Same two days, same seed
var dayA = Enumerable.Range(0, 10_000)
    .Select(_ => 20 + rng.NextDouble() * 180).ToArray();
var dayB = Enumerable.Range(0, 10_000)
    .Select(_ => rng.NextDouble() < 0.05
        ? 600 + rng.NextDouble() * 1_400
        : 20 + rng.NextDouble() * 60).ToArray();

// Nearest rank: the value that p% of requests are at or under
static double P(double[] ms, double p)
{
    var sorted = ms.Order().ToArray();
    return sorted[(int)Math.Ceiling(p / 100 * sorted.Length) - 1];
}

foreach (var (name, ms) in new[] { ("A", dayA), ("B", dayB) })
    Console.WriteLine($"Day {name}: p50 {P(ms, 50):F0}  " +
        $"p95 {P(ms, 95):F0}  p99 {P(ms, 99):F0} ms");
// Day A: p50 110  p95 191  p99 198 ms
// Day B: p50 52  p95 80  p99 1728 ms
